import "core-js/modules/es6.number.constructor";
import { mapGetters } from 'vuex';
import HiddenDetial from "./hiddenDetial";
import { hiddenList, hiddenDelete, securityDelete } from "@/api/safeDanger/hiddenCategory";
// import {getHiddenPCDict} from "@/utils/hiddenDict";

export default {
  name: "hiddenTable",
  components: {
    HiddenDetial: HiddenDetial
  },
  props: {
    category: {
      type: String,
      default: null
    },
    roomId: {
      type: Number
    },
    isEdit: {
      type: Boolean,
      default: false
    },
    fromType: {
      type: String,
      default: null
    },
    yhbz: {
      type: String,
      default: null
    }
  },
  data: function data() {
    return {
      detailObj: {},
      // options: getHiddenPCDict,
      options: [],
      tableList: [],
      loading: false,
      tableHeight: undefined,
      // 查询参数
      queryParams: {
        categoryId: '',
        type: ''
      },
      multipleSelection: [],
      hiddenDialogVisible: false,
      hiddenDialogTitle: '',
      hiddenType: false
    };
  },
  created: function created() {
    this.getList();
  },
  mounted: function mounted() {},
  methods: {
    handleQuery: function handleQuery() {
      this.getList();
    },
    resetQuery: function resetQuery() {
      this.resetForm("queryForm");
      this.handleQuery();
    },
    handleAdd: function handleAdd() {
      this.hiddenDialogTitle = '新增';
      this.hiddenDialogVisible = true;
      this.hiddenType = 'add';
    },
    formatRectificationStatus: function formatRectificationStatus(row) {
      if (row.rectificationStatus == 1) {
        return '已整改';
      } else {
        return '未整改';
      }
    },
    closeDialog: function closeDialog() {
      this.hiddenDialogVisible = false;
      this.getList();
    },
    getList: function getList() {
      var _this = this;
      this.queryParams.categoryId = this.roomId;
      this.loading = true;
      if (this.fromType == 'yhtb') {
        //来自隐患提报
        this.queryParams.type = this.yhbz;
      }
      hiddenList(this.queryParams).then(function (response) {
        _this.tableList = response.data;
      }).finally(function () {
        _this.loading = false;
      });
    },
    handleSelectionChange: function handleSelectionChange(val) {
      this.ids = [];
      this.multipleSelection = val;
    },
    btnClick: function btnClick(row) {
      this.$emit('select', row);
    },
    handleUpdate: function handleUpdate() {
      this.hiddenDialogTitle = '修改';
      this.detailObj = this.multipleSelection[0];
      this.hiddenDialogVisible = true;
      this.hiddenType = 'edit';
    },
    handleDel: function handleDel() {
      var _this2 = this;
      this.$confirm('是否确认删除选中数据项?', "警告", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      }).then(function () {
        hiddenDelete(_this2.multipleSelection.map(function (item) {
          return item.id;
        })).then(function (res) {
          _this2.$message.success(res.msg);
          _this2.getList();
        });
      });
    },
    handleClose: function handleClose() {
      this.hiddenDialogVisible = false;
      this.getList();
    }
  }
};
